import{_ as a}from"./chunks/grf_500.U7eOTPpf.js";import{_ as r,o as t,c as i,al as o}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Lightware GRF250/GRF500 Gimbal Lidar","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sensor/grf_lidar.md","filePath":"zh/sensor/grf_lidar.md"}'),n={name:"zh/sensor/grf_lidar.md"};function l(d,e,s,h,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="lightware-grf250-grf500-gimbal-lidar" tabindex="-1">Lightware GRF250/GRF500 Gimbal Lidar <a class="header-anchor" href="#lightware-grf250-grf500-gimbal-lidar" aria-label="Permalink to &quot;Lightware GRF250/GRF500 Gimbal Lidar&quot;">​</a></h1><p>LightWare <a href="https://lightwarelidar.com/shop/grf-250/" target="_blank" rel="noreferrer">GRF250</a> and <a href="https://lightwarelidar.com/shop/grf-500/" target="_blank" rel="noreferrer">GRF500</a> are small and light Lidar modules with a range of 250m and 500m, respectively.</p><p><img src="'+a+'" alt="LightWare GRF250 Gimbal Lidar"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Lidar driver is not included in the default build of PX4. You will need to <a href="#add-the-driver-to-the-px4-build">create and use a custom build</a>.</p></div><h2 id="购买渠道" tabindex="-1">购买渠道 <a class="header-anchor" href="#购买渠道" aria-label="Permalink to &quot;购买渠道&quot;">​</a></h2><p>Order these modules from:</p><ul><li><a href="https://lightwarelidar.com/shop/grf-250/" target="_blank" rel="noreferrer">GRF250</a></li><li><a href="https://lightwarelidar.com/shop/grf-500/" target="_blank" rel="noreferrer">GRF500</a></li></ul><h2 id="硬件安装" tabindex="-1">硬件安装 <a class="header-anchor" href="#硬件安装" aria-label="Permalink to &quot;硬件安装&quot;">​</a></h2><p>The rangefinder can be connected to any unused serial port, such as <code>TELEM2</code>. <a href="#parameter-configuration">Parameter Configuration</a> explains how to configure the port to use and the other properties of the rangefinder.</p><h2 id="px4-setup" tabindex="-1">PX4 Setup <a class="header-anchor" href="#px4-setup" aria-label="Permalink to &quot;PX4 Setup&quot;">​</a></h2><h3 id="add-the-driver-to-the-px4-build" tabindex="-1">Add the Driver to the PX4 Build <a class="header-anchor" href="#add-the-driver-to-the-px4-build" aria-label="Permalink to &quot;Add the Driver to the PX4 Build&quot;">​</a></h3><p>The <a href="./../modules/modules_driver_distance_sensor#lightware-grf-serial">lightware_grf_serial</a> driver for this Lidar is not included in PX4 firmware by default. In order to use these modules you will first need to update the firmware configuration to add the driver, and then build the firmware.</p><ol><li><p>Update the firmware configuration. You can use either of the following options:</p><ul><li><p>Menuconfig:</p><ol><li>Install and open <a href="./../hardware/porting_guide_config#px4-menuconfig-setup">menuconfig</a></li><li>In <a href="./../hardware/porting_guide_config#px4-menuconfig-setup">menuconfig</a>, navigate to <strong>Drivers &gt; Distance sensors</strong></li><li>Select/Enable <code>lightware_grf_serial</code></li><li>Save the configuration</li></ol></li><li><p>Manually update <code>default.px4</code> to include the configuration key:</p><ol><li><p>Open the <code>default.px4board</code> config file that corresponds to the board you want to build for. For example, to add the driver to <code>fmu-v6x</code> boards you would update <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6x/default.px4board" target="_blank" rel="noreferrer">/boards/px4/fmu-v6x/default.px4board </a></p></li><li><p>Add the following line and save the file:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_DRIVERS_DISTANCE_SENSOR_LIGHTWARE_GRF_SERIAL=y</span></span></code></pre></div></li></ol></li></ul></li><li><p><a href="./../dev_setup/building_px4">Build PX4</a> for your flight controller target and upload the new firmware.</p></li></ol><h3 id="parameter-configuration" tabindex="-1">Parameter Configuration <a class="header-anchor" href="#parameter-configuration" aria-label="Permalink to &quot;Parameter Configuration&quot;">​</a></h3><p>You will need to configure PX4 to indicate the serial port to which the sensor is connected (as per <a href="./../peripherals/serial_configuration">Serial Port Configuration</a>) and also the orientation and other properties of the sensor.</p><p>The <a href="./../advanced_config/parameters">parameters to change</a> are listed in the table.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>描述</th></tr></thead><tbody><tr><td><a id="SENS_EN_GRF_CFG"></a><a href="./../advanced_config/parameter_reference#SENS_EN_GRF_CFG">SENS_EN_GRF_CFG</a></td><td>Set to the serial port the sensor is connected to.</td></tr><tr><td><a id="GRF_RATE_CFG"></a><a href="./../advanced_config/parameter_reference#GRF_RATE_CFG">GRF_RATE_CFG</a></td><td>Set the update rate.</td></tr><tr><td><a id="GRF_SENS_MODEL"></a><a href="./../advanced_config/parameter_reference#GRF_SENS_MODEL">GRF_SENS_MODEL</a></td><td>Set the sensor model to use.</td></tr></tbody></table><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p>You can confirm that the sensor is correctly configured by connecting QGroundControl, and observing that <a href="https://mavlink.io/en/messages/common.html#DISTANCE_SENSOR" target="_blank" rel="noreferrer">DISTANCE_SENSOR</a> is present in the <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_inspector.html" target="_blank" rel="noreferrer">MAVLink Inspector</a>.</p><p>Moving the sensor around at various distances from a surface will have the <code>current_distance</code> value change.</p><h2 id="故障处理" tabindex="-1">故障处理 <a class="header-anchor" href="#故障处理" aria-label="Permalink to &quot;故障处理&quot;">​</a></h2><p>If you are having problems with connecting to the sensor you may need to unassign a the default serial port. <a href="./../peripherals/serial_configuration">Unassign Default Serial Port</a></p>',22)])])}const _=r(n,[["render",l]]);export{g as __pageData,_ as default};
